              <input class="search_btn" type="submit" value=" ">
          </form>
        </div>        
      </div>

      <!-- Slider -->
      <div class="slider_post_wrapper">
        {% set featured_posts = blog_recent_topic_posts('{{ group.id }}', 'Featured', 3) %}
